+            throw new IllegalArgumentException("Group by field must not be null or empty");
+        }
+
+        String trimmedField = groupByField.trim();
+        if (!ALLOWED_GROUP_BY_FIELDS.contains(trimmedField)) {
+            throw new IllegalArgumentException(
+                    "Invalid group by field: '" + trimmedField + "'. Allowed fields: " + ALLOWED_GROUP_BY_FIELDS);
+        }
+
+        // Validate and parse dateRange
+        if (dateRange == null || dateRange.trim().isEmpty()) {
+            throw new IllegalArgumentException("Date range must not be null or empty");
+        }
+
+        String[] parts = dateRange.split(",", -1);
+        if (parts.length != 2) {
+            throw new IllegalArgumentException(
+                    "Invalid date range format. Expected 'startDate,endDate' (e.g. '2024-01-01,2024-12-31')");
